var a=`0897-phaksha-paa`;var n=`world-0897`;var t=`BT`;var s=`south-asia`;var l=4;var r=49;var o={en:`Phaksha Paa`,ua:`Пакша паа`};var h={en:`Phaksha Paa is a Bhutan dish made with pork belly, yellow onion, daikon, red bell pepper. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пакша паа, страва кухні країни Бутан. Основні складники: свиняча грудинка, жовта цибуля, дайкон, червоний солодкий перець. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`pork-belly`,760,`g`],[`canola-oil`,45,`ml`],[`yellow-onion`,150,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 34 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 34 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:34,i:[[`daikon`,380,`g`],[`red-bell-pepper`,160,`g`],[`dried-arbol-chilies`,4,`pcs`],[`water`,320,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`]]}];var g={slug:a,id:n,country:`BT`,region:s,servings:4,minutes:49,title:o,text:h,steps:d};export{t as country,g as default,n as id,r as minutes,s as region,l as servings,a as slug,d as steps,h as text,o as title};